using GameplayCore.Entities; using ZombieWar.Features.Targeting.Registry; using ZombieWar.Features.Boss.Ports;
namespace ZombieWar.Integration.Boss { public sealed class BossTargetRegistrationAdapter:IBossTargetRegistrationPort { private readonly ITargetRegistry _registry;private BossCombatBridge _candidate;public BossTargetRegistrationAdapter(ITargetRegistry registry){_registry=registry;}public void Bind(BossCombatBridge candidate)=>_candidate=candidate;public void Register(EntityId id){if(_candidate!=null)_registry.Register(_candidate);}public void Unregister(EntityId id)=>_registry.Unregister(id); } }
